import React, { useState } from 'react';
import './UserNumber.css';
import axios from 'axios';
import { Link } from 'react-router-dom';

function UserNumber() {
  const [number, setNumber] = useState('');

  const handleClick = (num) => {
    setNumber(prev => prev + num.toString());
  };

  const handleSubmit = async () => {
    if (number) {
      try {
        await axios.post('http://localhost:8080/set_number', { number }); // Changed to 8080
        console.log('Number sent:', number);
        setNumber('');
      } catch (error) {
        console.error('Error:', error);
      }
    }
  };

  const handleReset = () => {
    setNumber('');
  };

  const digits = Array.from({ length: 10 }, (_, i) => i);

  return (
    <div className="section5-wrapper">
      <header className="section5-header">
        <div className="logo">
          <h1>SonicGLow<br />Cube</h1>
        </div>
        <nav>
          <ul>
            <li><Link to="/">Home</Link></li>
            <li><Link to="/resources">Resources</Link></li>
            <li><Link to="/cube">SonicGlow Cube</Link></li>
            <li><Link to="/about">About Us</Link></li>
          </ul>
        </nav>
      </header>

      <main className="section5-main">
        <div className="display-area">
          {number || 'Number'}
        </div>

        <div className="button-grid">
          {digits.map(d => (
            <button
              key={d}
              className="num-btn"
              onClick={() => handleClick(d)}
            >
              {d}
            </button>
          ))}
        </div>

        <div className="submit-container">
          <button className="action-button" onClick={handleSubmit}>Submit</button>
          <button className="action-button" onClick={handleReset}>Reset</button>
        </div>
      </main>
    </div>
  );
}

export default UserNumber;
